/**
 * The carpet: the exhibit floor's own outline, in the same page points.
 *
 * The single filled polygon the sheet draws the floor as. It is x 27-1138 y 160-777
 * points, which at the printed module is 282.2 m across, and the six
 * halls together measure 282.5 m. That agreement is why the whole sheet can be
 * laid down as one piece.
 */
const COMPILED_PLAN_FLOOR: ReadonlyArray<readonly [number, number]> = [
  [27.45, 777.3],
  [27.45, 302.23],
  [823.46, 302.23],
  [823.46, 160.05],
  [1138.44, 160.05],
  [1138.44, 585.04],
  [1128.75, 585.04],
  [440.61, 720.88],
  [440.61, 736.89],
  [269.5, 777.3],
];

/**
 * The five ways on to the floor, each pushed from its label on to the wall it
 * names. Page points. These are what the placement is lined up by.
 */
const COMPILED_PLAN_ENTRANCES: ReadonlyArray<{ x: number; y: number }> = [
  { x: 147.89, y: 302.23 },
  { x: 391.47, y: 302.23 },
  { x: 27.45, y: 626.22 },
  { x: 650.72, y: 302.23 },
  { x: 823.46, y: 270.12 },
];

/**
 * The pack's copy of this table where one is held, else what was built.
 *
 * Laid over per constant, so a refresh can carry one of these and
 * leave the rest alone, and a key that arrives the wrong shape leaves
 * the compiled value standing. See `fromPack`.
 */
const PACKED = fromPack('booth-plan', {
  PLANNED_BOOTHS: COMPILED_PLANNED_BOOTHS,
  PLAN_FLOOR: COMPILED_PLAN_FLOOR,
  PLAN_ENTRANCES: COMPILED_PLAN_ENTRANCES,
});

export const PLANNED_BOOTHS = PACKED.PLANNED_BOOTHS;
export const PLAN_FLOOR = PACKED.PLAN_FLOOR;
export const PLAN_ENTRANCES = PACKED.PLAN_ENTRANCES;
